  "prompt": "prompts/physics_committee_luna_opening_v1.md",
  "rankings": [
    {
      "rank": 1,
      "ballot_id": "B016",
      "proposed_laureates": [
        "Alexandre Blais",
        "Andreas Wallraff",
        "Robert J. Schoelkopf",
        "Steven M. Girvin"
      ],
      "assessment": {
        "nobel_worthiness": "Circuit QED made superconducting artificial atoms into controllable light-matter systems, opening a new regime of microwave quantum optics and enabling a major platform for quantum information. The foundational physics merits serious recognition independently of eventual computing applications.",
        "attribution": "The theory, experimental realization, and broader framework developed through complementary contributions by all four nominees. A prize would need to distinguish foundational circuit-QED work from the much larger later field it enabled.",
        "maturity": "The central effects have been reproduced widely, and the platform has matured over two decades into a powerful setting for quantum control and measurement.",
        "uncertainties": [
          "The discovery's boundaries and the relative credit among the many early contributors require careful historical assessment."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B001",
      "proposed_laureates": [
        "Juan Ignacio Cirac",
        "Peter Zoller",
        "Rainer Blatt"
      ],
      "assessment": {
        "nobel_worthiness": "The ion-trap proposals and experiments established a clear route from individual quantum systems to controlled gates and simulation, with lasting influence on quantum information and precision control.",
        "attribution": "Cirac and Zoller supplied central theoretical proposals, while Blatt's experiments helped demonstrate and develop the platform. The three names represent complementary contributions, though the field's wider experimental history should be considered.",
        "maturity": "Ion-trap gates and small processors have been demonstrated and refined across laboratories over many years; the fundamental platform is robust even as scale-up remains active.",
        "uncertainties": [
          "The boundary between the early enabling work and later advances by other ion-trap groups is not sharp."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B049",
      "proposed_laureates": [
        "Alexei Kitaev",
        "Andrew M. Steane",
        "Peter W. Shor"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction and fault tolerance resolved the apparent incompatibility between fragile quantum states and scalable computation, establishing a deep and influential body of physics and information theory.",
        "attribution": "Shor and Steane introduced seminal error-correcting codes, while Kitaev developed foundational topological approaches. The three represent distinct, major strands of the subject.",
        "maturity": "The theory is firmly established, and experiments increasingly demonstrate error correction and improved logical performance. Full fault-tolerant operation remains an unfinished technological goal.",
        "uncertainties": [
          "The extent to which a prize should recognize theoretical foundations before large-scale fault-tolerant computation is achieved remains a judgment call."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B008",
      "proposed_laureates": [
        "Michael Berry",
        "Yakir Aharonov"
      ],
      "assessment": {
        "nobel_worthiness": "The Aharonov-Bohm effect and Berry phase revealed that quantum phases have observable consequences beyond local force-based descriptions, reshaping understanding across quantum mechanics and many areas of physics.",
        "attribution": "Aharonov's work established the significance of electromagnetic potentials for quantum phases, while Berry identified the general geometric phase. Their contributions are distinct and highly influential.",
        "maturity": "The effects are deeply established experimentally and theoretically, with decades of use across distinct physical systems.",
        "uncertainties": [
          "The combined framing joins related but historically distinct discoveries, and the experimental history includes important contributions beyond these two nominees."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B014",
      "proposed_laureates": [
        "Eli Yablonovitch",
        "John D. Joannopoulos",
        "Sajeev John"
      ],
      "assessment": {
        "nobel_worthiness": "Photonic crystals and photonic band gaps introduced a powerful way to control the propagation and emission of light through structured media, influencing fundamental optics and device physics.",
        "attribution": "Yablonovitch and John independently articulated central photonic-band-gap ideas, while Joannopoulos contributed influential theory and development of the field. The allocation among proposal, demonstration, and theory deserves care.",
        "maturity": "The physical principles are well confirmed and underpin a mature research area, although the most ambitious forms of complete optical control remain challenging.",
        "uncertainties": [
          "The breadth of the field makes it difficult to isolate the decisive discovery and delimit its principal contributors."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B024",
      "proposed_laureates": [
        "Immanuel Bloch",
        "Markus Greiner",
        "Peter Zoller",
        "Tilman Esslinger"
      ],
      "assessment": {
        "nobel_worthiness": "Ultracold atoms in optical lattices made strongly interacting many-body systems unusually controllable and gave researchers a clean route to quantum simulation, with major basic-physics impact.",
        "attribution": "The credited theorist and experimentalists represent important complementary roles in proposals, early demonstrations, and development of the platform. Contributions across several laboratories make exact division of credit difficult.",
        "maturity": "The platform has been established for decades and supports increasingly sophisticated experiments; its value as a simulator is clear, though the scope of problems it can decisively solve continues to develop.",
        "uncertainties": [
          "The credited group spans a broad program rather than one sharply bounded discovery, and other groups made essential contributions."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B035",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks pushed precision measurement into a new regime and created a robust platform for tests of fundamental physics and applications of precise timekeeping.",
        "attribution": "Katori and Ye made leading, complementary contributions to the lattice-clock concept and its realization. The field has a broader community, but these two are central figures.",
        "maturity": "The clocks have been repeatedly demonstrated at extraordinary precision and are a mature experimental achievement, even as further improvements continue.",
        "uncertainties": [
          "The prize case depends on whether the achievement is framed as a fundamental advance in measurement physics or primarily as precision technology."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B026",
      "proposed_laureates": [
        "Ataç İmamoğlu",
        "Jörg Wrachtrup",
        "Ronald Hanson"
      ],
      "assessment": {
        "nobel_worthiness": "Optical control of solid-state spins and spin-photon entanglement linked individual defects to optical networks, creating important opportunities for quantum optics, sensing, and communication.",
        "attribution": "The nominees represent key theoretical and experimental advances in optically addressed spins and remote spin-photon connections. The discovery combines several lines of work that should be disentangled in assessing credit.",
        "maturity": "Single-spin control and photon-mediated entanglement have been demonstrated repeatedly, while scaling reliable network nodes and applications remains an active challenge.",
        "uncertainties": [
          "The combined discovery spans distinct centers and milestones, and its eventual fundamental impact relative to its technological promise is still developing."
        ]
      }
    }
  ]
}
